const sraw = $('Fetch Owner Suggest').first().json.data ?? $('Fetch Owner Suggest').first().json;
const sm = String(sraw).match(/window\.google\.ac\.h\(([\s\S]*)\)\s*;?\s*$/);
let queries = [];
if (sm) { try { queries = (JSON.parse(sm[1])[1] || []).map((x) => String(x[0] || '').trim()).filter((t) => t.length >= 3).slice(0, 12); } catch (e) { queries = []; } }
const nraw = String($('Fetch Egypt Dental News').first().json.data ?? $('Fetch Egypt Dental News').first().json);
const news = [];
const re = /<item>[\s\S]*?<title>([^<]*)<\/title>[\s\S]*?<source[^>]*>([^<]*)<\/source>/g;
let m = null;
while ((m = re.exec(nraw)) && news.length < 8) { news.push({ title: m[1].trim().slice(0, 140), source: m[2].trim().slice(0, 40) }); }
if (!queries.length && !news.length) throw new Error('Owner signals empty: suggest+RSS both failed');
return [{ json: { queries, news } }];

const raw = String(($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message && $input.first().json.choices[0].message.content) || '');
const lines = [];
const rawLines = String(raw).split('\n');
const headRe = /^\s*(Item\s*\d+\s*:|\d+\s*[.)\-\u2013:]\s*|[-\u2022]\s*)/i;
const used = {};
for (let li = 0; li < rawLines.length && lines.length < 7; li++) {
  if (used[li] || !headRe.test(rawLines[li])) continue;
  let chunk = (rawLines[li] + ' ' + (rawLines[li + 1] || '') + ' ' + (rawLines[li + 2] || '')).replace(/[*_`#\[\]()]/g, ' ').replace(/\s+/g, ' ').trim();
  chunk = chunk.replace(/^(Item\s*\d+\s*:|[-\u2022]\s*|\d+\s*[.)\-\u2013:]\s*)/i, '').trim().slice(0, 240);
  const hasAr = /[\u0600-\u06FF]/.test(chunk);
  const isEcho = /(prohibited|no explanation|outside the list|user questions:|questions searched|input data|format:|\bnote\b|identify|key themes|analysis:|analyz)/i.test(chunk);
  if (isEcho) continue;
  if (chunk.length > 25 && hasAr && !/:$/.test(chunk)) { if (lines.indexOf(chunk) < 0) { lines.push(chunk); used[li] = 1; used[li + 1] = 1; used[li + 2] = 1; } }
}
if (!lines.length) throw new Error('Pulse parse found zero pain lines');
const qs = $('Extract Owner Signals').first().json;
const PLAYS = [
  [/فائض|منافس|زحمة|مزدحم|سوق/, 'حاسبة الخسارة: فيديو + CTA ديمو'],
  [/مجان|سعر|تكلفة|رخيص|غالي|فلوس|اشتراك/, 'إسفين مجاني: تدقيق مكالمات + مقارنة المجاني بالمدفوع'],
  [/سمعة|فضيحة|ثقة|تقييم|ريفيو|سوشيال/, 'احترافية الرد: واتساب رسمي بلا أخطاء'],
  [/ترخيص|نقابة|غلق|امتثال|قانون|تنظيم/, 'باب الامتثال: محتوى تنظيمي + ديمو'],
  [/سرقة|أمان|ضياع|ورق|فوضى|نسخ|أرش/, 'الأرشفة حماية: نسخ احتياطي وسجلات'],
  [/حجز|مكالمة|سكرتيرة|موعد|انتظار|استقبال/, 'الاستقبال الذكي: رد فوري 24/7'],
];
const playFor = (line) => { for (const [re, play] of PLAYS) { if (re.test(line)) return play; } return 'وثق الحالة + اربطها بالحجز'; };
const head = 'نبض الجمهور اليومي\n\nهم يبحثون عن:\n' + qs.queries.slice(0, 6).map((q) => '- ' + String(q).replace(/[*_`#\[\]()]/g, '')).join('\n') + '\n\nالامهم (من التحليل):\n' + lines.map((l, i) => (i + 1) + '. ' + l).join('\n\n');
const uses = lines.map((l) => '- ' + playFor(l)).join('\n');
const full = head + '\n\nالاستغلال البيعي:\n' + uses;
return [{ json: { digest: full.slice(0, 3800) } }];
